#include <iostream>
#include <vector>
using namespace std;

int main() {
    int n;
    cin >> n;
    vector<int> a(n);
    int totalOnes = 0;
    for (int i = 0; i < n; i++) {
        cin >> a[i];
        if (a[i] == 1) totalOnes++;
    }

    // gain[i] = +1 if a[i]==0 (flipping turns it to 1, gain +1)
    //           -1 if a[i]==1 (flipping turns it to 0, gain -1)
    vector<int> gain(n);
    for (int i = 0; i < n; i++) {
        gain[i] = (a[i] == 0) ? 1 : -1;
    }

    // Find maximum subarray sum (Kadane's algorithm), must pick at least one element
    int maxSoFar = gain[0];
    int maxEndingHere = gain[0];
    for (int i = 1; i < n; i++) {
        maxEndingHere = max(gain[i], maxEndingHere + gain[i]);
        maxSoFar = max(maxSoFar, maxEndingHere);
    }

    cout << (totalOnes + maxSoFar) << endl;

    return 0;
}
